class Provider {

    api = "https://nyaa.si"

    getSettings() {
        return {
            canSmartSearch: true,
            smartSearchFilters: ["batch", "episodeNumber", "resolution", "query", "bestReleases"],
            supportsAdult: false,
            type: "main",
        }
    }

    async search(opts) {
        const rows = await this.fetchRows(`/?f=0&c=1_2&q=${encodeURIComponent(opts.query)}&s=seeders&o=desc`)
        return rows.map(r => this.toAnimeTorrent(r))
    }

    async smartSearch(opts) {
        const parts = []
        if (opts.query) {
            parts.push(opts.query)
        } else {
            const title = opts.media.englishTitle || opts.media.romajiTitle || ""
            if (title) parts.push(title)
        }
        if (opts.resolution) parts.push(this.formatResolution(opts.resolution))
        const q = parts.join(" ").trim()
        const rows = await this.fetchRows(`/?f=0&c=1_2&q=${encodeURIComponent(q)}&s=seeders&o=desc`)
        let results = rows.map(r => this.toAnimeTorrent(r))
        if (opts.resolution) {
            const res = opts.resolution.toLowerCase()
            results = results.filter(t => { const name = t.name.toLowerCase(); return name.includes(res) || name.includes(res.replace("p", "")) })
        }
        if (opts.batch) {
            results = results.filter(t => this.looksLikeBatch(t.name))
            results.forEach(t => { t.isBatch = true })
        } else if (opts.episodeNumber > 0) {
            results = results.filter(t => t.episodeNumber === -1 || t.episodeNumber === opts.episodeNumber)
        }
        if (opts.bestReleases) {
            const best = this.pickBestReleases(results)
            if (best.length > 0) { best.forEach(t => { t.isBestRelease = true }); return best }
        }
        return results
    }

    async getTorrentInfoHash(torrent) { return torrent.infoHash || "" }
    async getTorrentMagnetLink(torrent) { return torrent.magnetLink || "" }

    async getLatest() {
        const rows = await this.fetchRows("/?f=0&c=1_2&s=id&o=desc")
        return rows.map(r => this.toAnimeTorrent(r))
    }

    async fetchRows(path) {
        const rsspath = path.replace("/?", "/?page=rss&")
        const url = `${this.api}${rsspath}`
        const response = await fetch(url, { headers: { "User-Agent": "Mozilla/5.0 (compatible; Seanime/1.0)", "Accept": "application/rss+xml, application/xml, text/xml" } })
        if (!response.ok) throw new Error(`AnimeSalt torrent: HTTP ${response.status} from Nyaa`)
        return this.parseRss(await response.text())
    }

    parseRss(xml) {
        const items = []
        const blocks = xml.match(/<item[\s\S]*?<\/item>/gi) || []
        for (const block of blocks) {
            const title = this.xmlText(block, "title")
            const link = this.xmlText(block, "link")
            if (!title || !link) continue
            const seeders = parseInt(this.xmlText(block, "nyaa:seeders") || "0", 10)
            const leechers = parseInt(this.xmlText(block, "nyaa:leechers") || "0", 10)
            const downloads = parseInt(this.xmlText(block, "nyaa:downloads") || "0", 10)
            const size = this.xmlText(block, "nyaa:size")
            const infoHash = (this.xmlText(block, "nyaa:infoHash") || "").toLowerCase()
            const magnetLink = this.xmlText(block, "nyaa:magnetLink") || (infoHash ? this.buildMagnet(infoHash, title) : "")
            items.push({ title, link, pubDate: this.xmlText(block, "pubDate"), seeders, leechers, downloads, size, infoHash, magnetLink, downloadUrl: link + "/download" })
        }
        return items
    }

    xmlText(xml, tag) {
        const esc = tag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
        const m = xml.match(new RegExp(`<${esc}[^>]*>([\\s\\S]*?)<\/${esc}>`, "i"))
        return m ? m[1].replace(/<![CDATA[|]]>/g, "").trim() : ""
    }

    buildMagnet(hash, name) {
        return `magnet:?xt=urn:btih:${hash}&dn=${encodeURIComponent(name)}&tr=${encodeURIComponent("udp://open.stealth.si:80/announce")}&tr=${encodeURIComponent("udp://tracker.opentrackr.org:1337/announce")}&tr=${encodeURIComponent("http://nyaa.tracker.wf:7777/announce")}`
    }

    toAnimeTorrent(item) {
        return {
            name: item.title, date: item.pubDate ? new Date(item.pubDate).toISOString() : new Date().toISOString(),
            size: this.parseSize(item.size), formattedSize: item.size || "",
            seeders: item.seeders, leechers: item.leechers, downloadCount: item.downloads,
            link: item.link, downloadUrl: item.downloadUrl,
            magnetLink: item.magnetLink || undefined, infoHash: item.infoHash || undefined,
            resolution: this.parseResolution(item.title), isBatch: this.looksLikeBatch(item.title),
            episodeNumber: this.parseEpisodeNumber(item.title), releaseGroup: this.parseReleaseGroup(item.title),
            isBestRelease: false, confirmed: false,
        }
    }

    parseSize(size) {
        if (!size) return 0
        const m = size.match(/([\d,.]+)\s*(GiB|MiB|KiB|GB|MB|KB|B)/i)
        if (!m) return 0
        const v = parseFloat(m[1].replace(",","")), u = m[2].toUpperCase()
        const mp = { GIB:1024**3,GB:1000**3,MIB:1024**2,MB:1000**2,KIB:1024,KB:1000,B:1 }
        return Math.round(v * (mp[u] || 1))
    }

    formatResolution(res) { return res.replace(/p$/i, "") }

    parseResolution(name) {
        const m = name.match(/\b(2160|1440|1080|720|480|360)p?\b/i)
        return m ? `${m[1]}p` : ""
    }

    parseEpisodeNumber(name) {
        const se = name.match(/\bS\d+E(\d+)\b/i); if (se) return parseInt(se[1], 10)
        const dash = name.match(/\s-\s(\d{1,4})(?:\s|v\d|\[|\.mkv|\.mp4)/i); if (dash) return parseInt(dash[1], 10)
        const e = name.match(/\bEP?(\d{1,4})\b/i); if (e) return parseInt(e[1], 10)
        return -1
    }

    parseReleaseGroup(name) { const m = name.match(/^\[([^\]]+)\]/); return m ? m[1] : "" }

    looksLikeBatch(name) {
        return /\b(batch|complete|vol\.?\s*\d+-\d+|\d+-\d+)\b/i.test(name) || /\bS\d+\b(?!\s*E\d+)/i.test(name)
    }

    pickBestReleases(torrents) {
        const top = ["subsplease","erai-raws","ember","judas","dual audio","blu-ray"]
        const scored = torrents.map(t => {
            let s = 0; const l = t.name.toLowerCase()
            for (const g of top) if (l.includes(g)) s += 30
            if (l.includes("1080")) s += 20
            if (l.includes("blu-ray") || l.includes("bluray")) s += 15
            s += Math.min(t.seeders, 200) / 10
            return { t, s }
        }).sort((a,b) => b.s - a.s)
        if (!scored.length) return []
        const threshold = scored[0].s * 0.8
        return scored.filter(x => x.s >= threshold).map(x => x.t)
    }
}
